require_once __DIR__ . '/../../includes/functions.php';require_once __DIR__ . '/../../auth/guard.php';require_once __DIR__ . '/../../config/database.php';require_once __DIR__ . '/../../includes/module2_helpers.php';requireAdmin();$id=(int)($_GET['id']??0);if($id<=0)redirect('index.php');$stmt=$pdo->prepare('SELECT * FROM LoaiCanHo WHERE MaLoai=:id');$stmt->execute([':id'=>$id]);$data=$stmt->fetch();if(!$data)redirect('index.php');$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){module2_require_csrf();$data['TenLoai']=trim((string)($_POST['TenLoai']??''));$data['GiaThueChuan']=trim((string)($_POST['GiaThueChuan']??''));$data['MoTa']=module2_clean_short_html((string)($_POST['MoTa']??''));if($data['TenLoai']===''||mb_strlen($data['TenLoai'])>50)$errors[]='Tên loại không hợp lệ.';if($data['GiaThueChuan']===''||!is_numeric($data['GiaThueChuan'])||(float)$data['GiaThueChuan']<0)$errors[]='Giá thuê chuẩn không hợp lệ.';if(!$errors){$stmt=$pdo->prepare('UPDATE LoaiCanHo SET TenLoai=:ten,GiaThueChuan=:gia,MoTa=:mota WHERE MaLoai=:id');$stmt->execute([':ten'=>$data['TenLoai'],':gia'=>(float)$data['GiaThueChuan'],':mota'=>$data['MoTa']?:null,':id'=>$id]);setFlash('success','Cập nhật loại căn hộ thành công.');redirect('index.php');}}$title='Sửa loại căn hộ';require_once __DIR__ . '/../../includes/header.php';
